// app/hifz/topics.ts — per-ayah study-topic map (ALL 6,236 ayahs).
// Generated by ~/workspace/topic-work/classify_topics.py — do not hand-edit;
// re-run the script instead. See topics-README.md for method + honesty notes.
//
// This is a STUDY AID, not tafsir: each ayah gets ONE primary topic from
// deterministic keyword rules over the Saheeh International translation,
// with hand-checked overrides for famous verses and a surah-theme fallback.
// The UI must label it as a study aid. No Quran text is stored here —
// only "surah:ayah" -> topic id. Quran text always comes from Quran.com.

export type TopicId =
  | 'tawhid'
  | 'prophets'
  | 'afterlife'
  | 'worship'
  | 'charity'
  | 'character'
  | 'nature'
  | 'guidance'
  | 'disbelief'
  | 'law'
  | 'family'
  | 'patience'
;

export interface Topic {
  id: TopicId;
  /** Display name, e.g. "Allah & Tawhid". */
  name: string;
  /** One-line description for the legend. */
  description: string;
  /** Main colour: dots, labels, active state. */
  color: string;
  /** Light wash: ayah background tint in Mushaf / surah views. */
  wash: string;
}

export const TOPICS: Topic[] = [
  { id: 'tawhid', name: 'Allah & Tawhid', description: 'Who Allah is — His oneness, names, attributes and power.', color: '#0B6E4F', wash: '#E3F2EC' },
  { id: 'prophets', name: 'Prophets & Stories', description: 'The messengers and the peoples before us — their stories and lessons.', color: '#6D28D9', wash: '#EFE7FB' },
  { id: 'afterlife', name: 'Afterlife & Judgement', description: 'The Day of Judgement, Paradise, the Fire, and the life to come.', color: '#9D174D', wash: '#FBE7F0' },
  { id: 'worship', name: 'Prayer & Worship', description: 'Salah, fasting, Hajj, dhikr, dua and drawing near to Allah.', color: '#1E40AF', wash: '#E3EAFB' },
  { id: 'charity', name: 'Charity & Justice', description: 'Giving, zakah, caring for the poor and standing for justice.', color: '#B45309', wash: '#FBF0DF' },
  { id: 'character', name: 'Morality & Character', description: 'Truthfulness, patience of character, forgiveness, good manners.', color: '#4D7C0F', wash: '#EFF6E2' },
  { id: 'nature', name: 'Nature & Creation', description: 'The heavens, the earth, the sea, animals and the signs in creation.', color: '#0E7490', wash: '#E2F2F6' },
  { id: 'guidance', name: 'Guidance & the Quran', description: 'The Quran itself, revelation, belief, and the straight path.', color: '#C2410C', wash: '#FBE9E1' },
  { id: 'disbelief', name: 'Disbelief & Hypocrisy', description: 'Rejection, hypocrisy, shirk, and those who turn away.', color: '#991B1B', wash: '#F9E3E3' },
  { id: 'law', name: 'Law & Rulings', description: 'Halal and haram, marriage, inheritance, contracts and penalties.', color: '#475569', wash: '#E9EDF1' },
  { id: 'family', name: 'Family & Society', description: 'Parents, spouses, children, kinship and life together.', color: '#A16207', wash: '#F8F0DA' },
  { id: 'patience', name: 'Patience & Trials', description: 'Trials, hardship, steadfastness, and relief after difficulty.', color: '#0369A1', wash: '#E1EFF8' },
];

export const TOPIC_BY_ID: Record<TopicId, Topic> = Object.fromEntries(
  TOPICS.map((t) => [t.id, t]),
) as Record<TopicId, Topic>;

