/** Topic for one ayah; falls back to 'guidance' for an unknown key. */
export function getAyahTopic(surah: number, ayah: number): TopicId {
  return AYAH_TOPICS[`${surah}:${ayah}`] ?? 'guidance';
}

export function getTopic(surah: number, ayah: number): Topic {
  return TOPIC_BY_ID[getAyahTopic(surah, ayah)];
}

